extension KeelClient {
    /// Keel version, API revision and the open library.
    public func version(_ params: [String: JSONValue]) async throws -> VersionResult {
        try await call("version", params: params, result: VersionResult.self)
    }
    /// The library's sources with their status.
    public func sources_list(_ params: [String: JSONValue]) async throws -> [SourcesListResultItem] {
        try await call("sources.list", params: params, result: [SourcesListResultItem].self)
    }
    /// Adds a folder, drive or share as a library source (index it with sources.index).
    public func sources_add(_ params: SourcesAddParams) async throws -> SourcesAddResult {
        try await call("sources.add", params: params, result: SourcesAddResult.self)
    }
